def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_residual = 0.1
    spread = 0.3
    return np.where(remaining >= 0, np.maximum(0.0, 1.0 - np.abs(remaining - optimal_residual) / spread), -1.0)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining > 0, item / remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target = 0.2
    return np.where(remaining >= 0, np.cos(np.pi * (remaining - target) / (2.0 * target + 1e-7)), -1.0)

